    requires n >= 0
    ensures result == fib4_value(n)
{
    var a, b, c, d := 0, 0, 2, 0; // fib4(0), fib4(1), fib4(2), fib4(3)
    if n == 0 {
        return 0;
    } else if n == 1 {
        return 0;
    } else if n == 2 {
        return 2;
    } else if n == 3 {
        return 0;
    }

