    var i := 4;
    while i <= n
        invariant 0 <= i <= n + 1
        invariant a == fib4_value(i - 4) && b == fib4_value(i - 3) && c == fib4_value(i - 2) && d == fib4_value(i - 1)
    {
        temp := a + b + c + d; // fib4(i) = fib4(i-1) + fib4(i-2) + fib4(i-3) + fib4(i-4)
